        int d = intlow2(c);
        c=(c&~d);
        c=(c|(d>1);
    } else {
        c=(c&~(1<1));
        c = zuhe_next_incur(c, n - 1， l+1);
        int d = intlow2(c);
        c=(c|(d>>1);
    }
    return c;
}
